BEGIN; INSERT INTO clinics(id,name,clerk_org_id) VALUES('ci-e23-a','CI E23 A','ci_e23_org_a'),('ci-e23-b','CI E23 B','ci_e23_org_b') ON CONFLICT(id) DO NOTHING; INSERT INTO reliability_targets(id,clinic_id,service_key,slo_target,rto_seconds,rpo_seconds) VALUES('ci-e23-target-a','ci-e23-a','api',0.999,3600,900) ON CONFLICT(id) DO NOTHING; SET ROLE authenticated; SELECT set_config('app.clerk_org_id','ci_e23_org_a',false); DO 'BEGIN IF NOT EXISTS(SELECT 1 FROM reliability_targets WHERE id=''ci-e23-target-a'') THEN RAISE EXCEPTION ''tenant A cannot read reliability target''; END IF; END'; SELECT set_config('app.clerk_org_id','ci_e23_org_b',false); DO 'BEGIN IF EXISTS(SELECT 1 FROM reliability_targets WHERE id=''ci-e23-target-a'') THEN RAISE EXCEPTION ''cross-tenant reliability read''; END IF; END'; RESET ROLE; ROLLBACK;